#include <stdio.h>
#include <string.h>

void reverse(char *s) {
    char *left = s;
    char *right = s + strlen(s) - 1;
    while (left < right) {
        char temp = *left;
        *left++ = *right;
        *right-- = temp;
    }
}

int main() {
    char word[] = "stressed";
    reverse(word);
    printf("%s\n", word);
    return 0;
}
